candidates.contract_code:
pub assume_specification[ CString::into_raw ](
    this: CString,
) -> (result: *mut c_char)
    ensures
        result.addr() != 0,
;

pub assume_specification<T: ?Sized, A: Allocator>[ Rc::<T, A>::as_ptr ](
    this: &Rc<T, A>,
) -> (result: *const T)
    ensures
        result.addr() != 0,
;
